<?php
require __DIR__ . '/../config/koneksi.php'; require_login();
$id=max(0,page_int('id'));
$order=statement($db,'SELECT p.id_pesanan AS id,p.id_user AS user_id,p.tanggal AS created_at,p.total AS total_amount,p.status AS status,p.metode_pembayaran AS payment_method,p.status_pembayaran AS payment_status,u.nama AS recipient_name,u.alamat AS address_current FROM pesanan p LEFT JOIN users u ON u.id_user=p.id_user WHERE p.id_pesanan=:id AND p.id_user=:user', ['id'=>$id,'user'=>(int)current_user()['id']])->fetch();
if (!$order) { http_response_code(404); exit('Pesanan tidak ditemukan.'); }
$items=statement($db,'SELECT d.id_detail AS id,d.id_pesanan AS order_id,d.id_buku AS book_id,b.judul_buku AS book_title,d.jumlah AS quantity,d.harga AS unit_price, CASE WHEN d.harga IS NOT NULL THEN d.harga*d.jumlah ELSE NULL END AS subtotal FROM detail_pesanan d LEFT JOIN buku b ON b.id_buku=d.id_buku WHERE d.id_pesanan=:id ORDER BY d.id_detail',['id'=>$id])->fetchAll();
$pageTitle='Detail Pesanan #'.$id; require __DIR__.'/../template/navbar.php';
?>
<div class="page-intro"><div class="container"><span class="eyebrow">PESANAN SAYA</span><h1>Detail Pesanan <em>#<?= $id ?></em></h1><p>Status pesanan: <?= e(ucfirst($order['status'])) ?></p></div></div>
<section class="section"><div class="container"><div class="admin-panel"><h2>Rincian Buku</h2><div class="table-scroll"><table><thead><tr><th>Judul</th><th>Jumlah</th><th>Harga Satuan</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td><?= e($it['book_title']) ?></td><td><?= (int)$it['quantity'] ?></td><td><?= ($it['unit_price']===null ? 'Tidak tercatat' : rupiah((int)$it['unit_price'])) ?></td><td><?= ($it['subtotal']===null ? 'Tidak tercatat' : rupiah((int)$it['subtotal'])) ?></td></tr><?php endforeach; ?></tbody></table></div><h3>Total: <?= rupiah((int)$order['total_amount']) ?></h3><p><strong>Akun pemesan:</strong> <?= e($order['recipient_name']) ?></p><p><strong>Metode pembayaran:</strong> <?= e($order['payment_method']) ?></p><p><strong>Status pembayaran:</strong> <?= e($order['payment_status']) ?></p><p><strong>Alamat akun saat ini (bukan riwayat alamat pesanan):</strong> <?= nl2br(e($order['address_current'] ?? 'Belum diisi')) ?></p><a class="btn btn-outline" href="<?= path('user/pesanan.php') ?>">← Kembali ke Pesanan Saya</a></div></div></section>
<?php require __DIR__.'/../template/footer.php'; ?>
